// Demo curricular: estructura (módulos / submódulos) independiente de los recursos.
// El backend futuro sustituirá este catálogo por datos de la API.
function item(id, title, kind, minutes, description, file, url) {
    return { id: id, title: title, kind: kind, minutes: minutes, description: description, file: file, url: url };
}
